var o={UNKNOWN_OPERATOR:({op:e,validOps:t})=>`Unknown condition operator: "${e}". Valid operators: ${t?.join(", ")}. Use is-truthy, is-eq, is-gt, etc.`,MISSING_OPERATOR:()=>"No condition operator found on <if>. Add at least one operator attribute: is-gt, is-lt, is-eq, is-truthy...",ELSE_AFTER_CONTENT:()=>"<else> must be the last direct child of <if>; nodes after it were counted as then. Move the <else>...</else> block to the end.",PARTIAL_NOT_FOUND:({name:e,available:t})=>{let a=t&&t.length?t.join(", "):"(no registered partials)";return`Partial not found: "${e}". Registered partials: ${a}. Is <template id="tpl-${e}"> defined?`},SLOT_NOT_FOUND:({slot:e,partial:t,available:a})=>{let n=a&&a.length?a.join(", "):"(no named slots defined)";return`Slot "${e}" not found in partial "${t}". Available slots: ${n}. Content for this slot was ignored.`},PARTIAL_MISSING_NAME:()=>'<partial> element is missing the "name" attribute. Use <partial name="..."></partial>.',PARTIAL_DEPTH_LIMIT:({depth:e})=>`Partial depth limit (${e}) reached (possible infinite loop). A partial may be calling itself directly or indirectly.`,TEMPLATE_NOT_FOUND:({name:e})=>`Template not found: "tpl-${e}". Is <template id="tpl-${e}"> present on the page?`,FOR_MISSING_ATTR:()=>'<for> element is missing the "each" and/or "as" attribute. Use <for each="array.path" as="item"></for>.',FOR_NOT_ARRAY:({path:e,type:t})=>`<for each="${e}"> value must be an array; got: ${t}. Is "${e}" an array in context or store?`,BINDING_MISSING_PATH:()=>'data-text attribute is empty; a store path is required. Use data-text="path.to.value".',BINDING_MISSING_DATA_ATTR:({attrName:e,key:t})=>`No data-${t} attribute found for {${t}} in "${e}"; binding skipped. Add data-${t}="store.path" or remove the {${t}} placeholder.`,UNSAFE_EVENT_ATTR:({attrName:e})=>`"${e}" is an event-handler attribute; reactive data cannot bind to it. Use data-on-{event} for events instead (see README).`,UNSAFE_URL_ATTR:({attrName:e})=>`"${e}" contained an unsafe URL protocol and was sanitized to an empty string. Allowed protocols: http, https, root-relative (/), or #anchor.`,LIVE_IF_MISSING_OP:()=>"<if data-live>: no valid condition operator found. Add one: is-gt, is-lt, is-eq, is-truthy, etc.",PIPELINE_DEPTH_LIMIT:({maxIter:e})=>`Render pipeline reached the ${e} iteration limit (possible infinite loop). Stopping. Is a partial calling itself?`,MOUNT_TEMPLATE_NOT_FOUND:({name:e,available:t})=>{let a=t&&t.length?t.join(", "):"(no registered templates)";return`mount(): template "${e}" not found. Registered templates: ${a}. Is <template id="tpl-${e}"> defined?`},MOUNT_INVALID_TARGET:({target:e})=>`mount(): invalid target "${String(e)}". Target must be a valid DOM Element or CSS selector string.`,MOUNT_TARGET_NOT_FOUND:({selector:e})=>`mount(): target element matching selector "${e}" was not found.`,MOUNT_HOOK_FAILED:({hook:e,error:t})=>`mount(): "${e}" lifecycle hook failed: ${t?.message||t||"unknown error"}.`,MOUNT_ALREADY_MOUNTED:()=>"mount(): target element is already mounted. Duplicate mounts on the same target are rejected. Unmount first.",FOR_MISSING_KEY:({templateName:e})=>`Reactive <for data-live>: missing "key" attribute. Add a key for efficient DOM updates. (template: ${e??"?"})`,FOR_DUPLICATE_KEY:({keyVal:e,templateName:t})=>`Reactive <for data-live>: key "${e}" appears on more than one element; keys must be unique. (template: ${t??"?"})`,MODEL_MISSING_PATH:()=>'data-model attribute is empty; a store path is required. Use data-model="path.to.value".',TABLE_FOSTER_PARENTING:({templateName:e})=>`<if>/<for>/<partial> cannot be used inside <table> \u2014 the HTML parser moves them outside. Solution: move the condition/loop outside the <table>, or treat the tbody as a partial. (template: ${e??"?"})`,SHOW_MISSING_PATH:()=>'data-show attribute is empty; a store path is required. Use data-show="path.to.value".',REF_MISSING_NAME:()=>'data-ref attribute is empty; a reference name is required. Use data-ref="name".',UNKNOWN_EVENT:({eventName:e,validEvents:t})=>`Unsupported event type: "data-on-${e}". Valid types: ${t?.map(a=>`data-on-${a}`).join(", ")}.`,UNKNOWN_KEY_MODIFIER:({eventName:e,validKeys:t})=>`Unknown key modifier: "data-on-${e}". Supported keys: ${t?.join(", ")}. E.g. data-on-keydown-enter, data-on-keyup-escape.`,HANDLER_NOT_FOUND:({name:e,available:t})=>{let a=t&&t.length?t.join(", "):"(no registered handlers)";return`Handler not found: "${e}". Registered handlers: ${a}. Is "${e}" defined in the handlers object passed to mount()?`},RESERVED_ATTR_NAME:({name:e})=>`"${e}" is reserved by lime-csr and cannot be used as a {x}/data-x placeholder. Reserved names: text, model, show, live, diff, and any name starting with "on-". Rename the placeholder.`,INDEXED_MODEL_PATH:({path:e})=>`data-model="${e}" contains a numeric index (e.g. items.0.name). This is unsafe: if the array is mutated, the path drifts to the wrong item. Use a reactive <for data-live key=...> loop and bind to the loop variable instead.`,COMPUTED_MANUAL_SET:({path:e})=>`Path "${e}" is managed by store.computed(). Manual store.set() will be overwritten on the next dep change. Use store.computed() or choose a different path.`,IN_PLACE_MUTATION:({path:e})=>`store.set("${e}", value): value is the SAME reference as the stored object/array. In-place mutation detected \u2014 subscribers will NOT fire. Pass a new reference, e.g. store.set("${e}", [...arr]) or {...obj}.`,UNKNOWN_DIFF_STRATEGY:({value:e,templateName:t})=>`<for data-live>: unknown data-diff value "${e}". Valid values: simple, lcs, replace (or omit the attribute). Falling back to "simple". (template: ${t??"?"})`,COMPUTED_WITHOUT_STORE:({paths:e})=>`mount(): the "computed" option (${e?.join(", ")}) requires a store; registration skipped. Pass a store in the same mount() options object.`,BATCH_FLUSH_LIMIT:({maxWaves:e})=>`store.batch(): flush reached the ${e||100} wave limit (possible infinite loop). Dropping remaining notifications. Break the cycle (e.g. use store.computed instead of mutual sets).`,PATH_CLOBBER:({key:e,path:t,type:a})=>`store.set("${t}", ...): segment "${e}" was a ${a}, not an object. Replacing with {}.`,MODULE_READ_FAILED:({module:e,error:t})=>`Module "${e??"unknown"}" read failed: ${t?.message||t||"unknown error"}.`,MODULE_SETUP_FAILED:({module:e,error:t})=>`Module "${e??"unknown"}" setup failed: ${t?.message||t||"unknown error"}.`,MODULE_UPDATE_FAILED:({module:e,error:t})=>`Module "${e??"unknown"}" update failed: ${t?.message||t||"unknown error"}.`,MODULE_CLEANUP_FAILED:({module:e,error:t})=>`Module "${e??"unknown"}" cleanup failed: ${t?.message||t||"unknown error"}.`,MODULE_TRIGGER_OVERRIDDEN:({module:e,overriddenBy:t,trigger:a})=>`Module "${e}" trigger "${a}" was overridden by higher-priority module "${t}".`,MODULE_WATCH_FAILED:({module:e,path:t,error:a})=>`Module "${e??"unknown"}" watch callback for "${t}" failed: ${a?.message||a||"unknown error"}.`,MODULE_STORE_REQUIRED:({module:e,path:t})=>`Module "${e??"unknown"}" watch("${t}") called without a store.`,MODULE_AFTER_CONNECT_FAILED:({module:e,error:t})=>`Module "${e??"unknown"}" afterConnect callback failed: ${t?.message||t||"unknown error"}.`,MODULE_HANDLER_FAILED:({handler:e,error:t})=>`Handler "${e??"unknown"}" execution failed: ${t?.message||t||"unknown error"}.`};export{o as default};
